  ).stdout
    .trim()
    .split("\n");
  if (!nodeBin || !pi) throw new Error("node and pi must be on PATH");
  const root = (
    await execFile("mktemp", ["-d", "/tmp/pit-ux-XXXXXX"], { raise: true })
  ).stdout.trim();
  const socket = `${root}/tmux.sock`;
  const target = "pitux:0.0";
  await execFile("mkdir", ["-p", `${root}/home`, `${root}/agent`, `${root}/sessions`], {
    raise: true,
  });
  // Pi reads mcp.json and settings.json from its agent directory.
  const agentFiles: Array<[string, unknown]> = [];
  if (mcpServers.length > 0) {
    const server = `${cwd}/.pi/skills/pit-terminal-ux/assets/fixture-mcp-server.mjs`;
    agentFiles.push([
      "mcp.json",
      {
        mcpServers: Object.fromEntries(
          mcpServers.map(([name, config]) => [
            name,
            { command: `${nodeBin}/node`, args: [server], ...config },
          ]),
        ),
      },
    ]);
  }
  if (input.codemodeMode)
    agentFiles.push(["settings.json", { codemode: { mode: input.codemodeMode } }]);
  for (const [file, contents] of agentFiles) {
    await execFile(
      `${nodeBin}/node`,
      [
        "-e",
        "require('node:fs').writeFileSync(process.argv[1], process.argv[2])",
        `${root}/agent/${file}`,
        JSON.stringify(contents, null, 2),
      ],
      { raise: true },
    );
  }
  const command = [
    "env",
    "-i",
    `PATH=${nodeBin}:/usr/bin:/bin`,
    `HOME=${root}/home`,
    `PI_CODING_AGENT_DIR=${root}/agent`,
    "TERM=xterm-256color",
    "LANG=C.UTF-8",
    "PI_OFFLINE=1",
    "PI_TELEMETRY=0",
    ...extraEnv.map(([name, value]) => `${name}=${value}`),
    pi,
    "-e",
    `${cwd}/src/index.ts`,
    "-e",
    `${cwd}/.pi/skills/pit-terminal-ux/assets/fixture-provider.ts`,
    ...builtins.flatMap((name) => ["-e", `builtin:${name}`]),
    "--no-extensions",
    "--no-skills",
    ...(input.skills ?? []).flatMap((skill) => ["--skill", `${cwd}/${skill}`]),
    "--no-context-files",
    "--no-prompt-templates",
    "--no-themes",
    "--no-builtin-tools",
    "--offline",
    "--approve",
    "--provider",
    "pit-ux-fixture",
    "--model",
    "fixture",
    "--api-key",
    "fixture-not-a-real-key",
    "--thinking",
    "off",
    "--session-dir",
    `${root}/sessions`,
    "--use-theme",
    input.theme ?? "dark",
    "--tui-mode",
    input.mode ?? "regular",
  ];
  // tmux runs the pane command through a shell, so every argument is single-quoted.
  const quoted = command.map((part) => `'${part.replaceAll("'", "'\\''")}'`).join(" ");
  const paneCommand = input.keepShell ? `${quoted}; exec sleep 86400` : quoted;
  await tmux(socket, [
